@use 'sass:math';

/**
 * Layout
 */
$sizeGlobalMaxWidth: 1440px;
$sizeWidthContent: 1168px;
$sizeWidthTextContent: 768px;

// Variable needed for xy-grid
$global-width: $sizeWidthContent;

/**
 * Font sizes
 */
$sizeFontMini: 10px;
$sizeFontTiny: 12px;
$sizeFontSmall: 14px;
$sizeFontRegular: 16px;
$sizeFontBiggerRegular: 18px;
$sizeFontMedium: 20px;
$sizeFontLarge: 24px;
$sizeFontSmallBig: 28px;
$sizeFontBig: 32px;
$sizeFontBiggerBig: 40px;
$sizeFontSmallHuge: 48px;
$sizeFontHuge: 56px;
$sizeFontGiant: 72px;

// Font-Size curves
$fontSizeCurves: (
  huge: (
    tiny: $sizeFontSmallBig,
    xsmall: $sizeFontBig,
    small: $sizeFontBiggerBig,
    medium: $sizeFontSmallHuge,
    large: $sizeFontHuge,
    xlarge: $sizeFontGiant,
  ),
  big: (
    tiny: $sizeFontLarge,
    small: $sizeFontSmallBig,
    medium: $sizeFontBig,
    large: $sizeFontBiggerBig,
    xlarge: $sizeFontSmallHuge,
  ),
  large: (
    tiny: $sizeFontBiggerRegular,
    medium: $sizeFontLarge,
    large: $sizeFontSmallBig,
    xlarge: $sizeFontBig,
  ),
  medium: (
    tiny: $sizeFontBiggerRegular,
    xsmall: $sizeFontMedium,
    medium: $sizeFontMedium,
    large: $sizeFontLarge,
    xlarge: $sizeFontSmallBig,
  ),
  // Leads & Blockquotes
  biggerRegular:
    (
      xsmall: $sizeFontBiggerRegular,
      small: $sizeFontMedium,
      large: $sizeFontMedium,
      xlarge: $sizeFontLarge,
    ),
  regular: (
    tiny: $sizeFontRegular,
    xsmall: $sizeFontBiggerRegular,
    large: $sizeFontBiggerRegular,
    xlarge: $sizeFontMedium,
  ),
  small: (
    tiny: $sizeFontSmall,
    small: $sizeFontRegular,
    large: $sizeFontBiggerRegular,
  ),
  smallModFontSizeH5H6: (
    tiny: $sizeFontSmall,
    small: $sizeFontSmall,
    medium: $sizeFontRegular,
    large: $sizeFontRegular,
    xlarge: $sizeFontBiggerRegular,
  ),
  tiny: (
    xsmall: $sizeFontTiny,
    small: $sizeFontSmall,
  ),
  xsmall: (
    tiny: $sizeFontTiny,
    small: $sizeFontSmall,
    medium: $sizeFontRegular,
    large: $sizeFontBiggerRegular,
  ),
  supersmall: (
    tiny: $sizeFontTiny,
    small: $sizeFontSmall,
    large: $sizeFontRegular,
  ),
);

$sizeFontBase: $sizeFontRegular;
$fontFamilyBase: 'InterRegular', Helvetica, sans-serif;
$fontFamilyBlack: 'InterBlack', 'Arial Black', Helvetica, sans-serif;
/**
 * Line heights
 */
$sizeLineHeightNarrower: 1;
$sizeLineHeightNarrow: 1.2;
$sizeLineHeightMedium: 1.3;
$sizeLineHeightBigger: 1.4;
$sizeLineHeightSubBase: 1.45;
$sizeLineHeightBase: 1.5;
$sizeLineHeightSuper: 1.8;

$lineHeightCurves: (
  nav: (
    tiny: $sizeLineHeightBase,
    xsmall: $sizeLineHeightMedium,
    medium: $sizeLineHeightBigger,
    xlarge: $sizeLineHeightBase,
  ),
);

/**
 * Breakpoints
 */
$sizeBreakpointZero: 0;
$sizeBreakpointTiny: 320px;
$sizeBreakpointXSmall: 400px;
$sizeBreakpointSmall: 600px;
$sizeBreakpointMedium: 840px;
$sizeBreakpointLarge: 1024px;
$sizeBreakpointXLarge: 1280px;

// Size Curves
$sizeMini: 4px;
$sizeTiny: 8px;
$sizeSmallRegular: 12px;
$sizeRegular: 16px;
$sizeSmallLarge: 20px;
$sizeLarge: 24px;
$sizeSmallBig: 28px;
$sizeBig: 32px;
$sizeBiggerBig: 40px;
$sizeSmallHuge: 48px;
$sizeHuge: 56px;
$sizeGiant: 80px;

$sizeCurves: (
  big: (
    tiny: $sizeHuge,
    medium: $sizeGiant,
  ),
  large: (
    tiny: $sizeBiggerBig,
    medium: $sizeHuge,
  ),
  smallerLarge: (
    tiny: $sizeBig,
    small: $sizeBiggerBig,
    xlarge: $sizeHuge,
  ),
  medium: (
    tiny: $sizeLarge,
    medium: $sizeBig,
    xlarge: $sizeBiggerBig,
  ),
  biggerRegular: (
    tiny: $sizeSmallLarge,
    medium: $sizeLarge,
    xlarge: $sizeBig,
  ),
  columnGap: (
    tiny: $sizeSmallRegular,
    small: $sizeRegular,
    medium: $sizeLarge,
    xlarge: $sizeBig,
  ),
  captionGap: (
    tiny: $sizeSmallRegular,
    small: $sizeRegular,
    medium: $sizeSmallLarge,
    large: $sizeLarge,
  ),
  regular: (
    tiny: $sizeSmallRegular,
    xsmall: $sizeRegular,
    medium: $sizeSmallLarge,
    xlarge: $sizeLarge,
  ),
  smallerRegular: (
    tiny: $sizeRegular,
    xsmall: $sizeSmallLarge,
    large: $sizeSmallLarge,
    xlarge: $sizeLarge,
  ),
  small: (
    tiny: $sizeSmallRegular,
    xlarge: $sizeRegular,
  ),
  tiny: (
    tiny: $sizeTiny,
    medium: $sizeSmallRegular,
    xlarge: $sizeRegular,
  ),
  mini: (
    tiny: $sizeTiny,
    xlarge: $sizeTiny,
  ),
  atomic: (
    tiny: $sizeMini,
    medium: $sizeTiny,
  ),
);

// Layout Wrapper Spacing
$wrapperSpacing: (
  tiny: $sizeSmallRegular,
  xsmall: $sizeRegular,
  small: $sizeBig,
  medium: $sizeBig,
  large: $sizeBiggerBig,
);

// Indentation curves
$indentCurve: (
  list: (
    tiny: $sizeRegular,
    small: $sizeLarge,
    xlarge: $sizeBig,
  ),
  benefits: (
    tiny: $sizeBig,
    medium: $sizeBiggerBig,
  ),
  quote: (
    tiny: 18px,
    xsmall: 22px,
    small: $sizeLarge,
  ),
  quoteParagraph: (
    tiny: $sizeRegular,
    medium: $sizeLarge,
    large: $sizeBig,
  ),
);

// used in video and image
$imageCustomSizes: (
