/**
 * Data-layer tests: seed records, source registry and overlay descriptors.
 * `node --test tests/` – no dependencies.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

const readJson = async (name) => JSON.parse(await readFile(new URL(`../public/data/${name}`, import.meta.url), 'utf8'));
const recordsFile = await readJson('records.json');
const sourcesFile = await readJson('sources.json');
const overlaysFile = await readJson('overlays.json');

test('records.json has a stated generation method and dates', () => {
  assert.ok(recordsFile.generatedAt, 'generatedAt');
  assert.match(recordsFile.generatedAt, /^\d{4}-\d{2}-\d{2}/);
  assert.ok(recordsFile.method, 'method explains how the data was obtained');
});

test('every record satisfies the D4 schema', () => {
  assert.ok(recordsFile.records.length >= 10, 'a useful seed set');
  const providerIds = new Set(sourcesFile.providers.map((p) => p.id));
  const seen = new Set();
  for (const record of recordsFile.records) {
    for (const field of ['id', 'title', 'providerId', 'institution', 'rights', 'recordUrl', 'thumbnail']) {
      assert.ok(record[field], `${record.id}: ${field} must be set`);
    }
    assert.match(record.id, /^[a-z0-9-]+:.+$/, `${record.id} id shape`);
    assert.ok(!seen.has(record.id), `${record.id} unique`);
    seen.add(record.id);
    assert.ok(providerIds.has(record.providerId), `${record.id}: provider ${record.providerId} is registered`);
    assert.match(record.recordUrl, /^https:\/\//, `${record.id}: recordUrl https`);
    assert.match(record.thumbnail, /^https:\/\//, `${record.id}: thumbnail https`);
    assert.ok(Number.isFinite(record.yearStart) && Number.isFinite(record.yearEnd), `${record.id}: years`);
    assert.ok(record.yearStart <= record.yearEnd, `${record.id}: yearStart <= yearEnd`);
    assert.ok(record.yearStart > 1200 && record.yearEnd < 2100, `${record.id}: plausible years`);
    if (record.extent) {
      const { west, east, south, north } = record.extent;
      assert.ok(west < east && south < north, `${record.id}: bbox order`);
      assert.ok(east <= 180 && west >= -180 && north <= 90 && south >= -90, `${record.id}: bbox range`);
    }
    if (record.geo) {
      assert.ok(Math.abs(record.geo.lat) <= 90 && Math.abs(record.geo.lon) <= 180, `${record.id}: geo range`);
    }
    // Publication date vs depicted date must stay distinguishable.
    if (record.depictedYearStart) assert.ok(record.depictedYearStart >= 1200, `${record.id}: depicted year`);
  }
});

test('records carry the fields the detail view needs', () => {
  const withManifest = recordsFile.records.filter((r) => r.iiifManifest).length;
  assert.equal(withManifest, recordsFile.records.length, 'every seed record links a IIIF manifest');
  for (const record of recordsFile.records) {
    assert.match(record.iiifManifest, /^https:\/\/www\.e-rara\.ch\/i3f\/v\d+\/\d+\/manifest$/, `${record.id}: manifest url`);
  }
});

test('source registry documents endpoints, rights and retrieval date', () => {
  assert.ok(sourcesFile.providers.length >= 2);
  for (const provider of sourcesFile.providers) {
    assert.ok(provider.id && provider.name && provider.operator, `${provider.id}: identity`);
    assert.ok(provider.homepage?.startsWith('https://'), `${provider.id}: homepage`);
    assert.ok(provider.rights, `${provider.id}: rights statement`);
    assert.ok(provider.attribution, `${provider.id}: attribution`);
    assert.ok(provider.retrievalDate, `${provider.id}: retrieval date`);
    if (provider.api) {
      for (const [kind, url] of Object.entries(provider.api)) {
        assert.ok(url.startsWith('https://'), `${provider.id}.${kind}: https endpoint (${url})`);
      }
    }
  }
});

test('overlay descriptors are real WMTS layers with attribution', () => {
  assert.ok(overlaysFile.overlays.length >= 3);
  for (const overlay of overlaysFile.overlays) {
    assert.ok(overlay.id.startsWith('ch.swisstopo.'), `${overlay.id}: swisstopo layer id`);
    assert.match(overlay.urlTemplate, /^https:\/\/wmts\.geo\.admin\.ch\/1\.0\.0\//, `${overlay.id}: wmts template`);
    assert.ok(overlay.urlTemplate.includes('{TileMatrix}') && overlay.urlTemplate.includes('{TileCol}') && overlay.urlTemplate.includes('{TileRow}'), `${overlay.id}: tile placeholders`);
    assert.ok(Array.isArray(overlay.timeValues) && overlay.timeValues.length >= 1, `${overlay.id}: time values`);
    assert.ok(overlay.attribution, `${overlay.id}: attribution`);
    if (overlay.extent) {
      const { west, east, south, north } = overlay.extent;
      assert.ok(west < east && south < north, `${overlay.id}: bbox order`);
    }
  }
});

test('the Zeitreise layer exposes the documented historical editions', () => {
  const timeReise = overlaysFile.overlays.find((o) => o.id === 'ch.swisstopo.zeitreihen');
  assert.ok(timeReise, 'ch.swisstopo.zeitreihen present');
  assert.ok(timeReise.timeValues.length > 100, 'many editions');
  assert.ok(timeReise.timeValues.every((t) => /^\d{8}$/.test(t)), 'YYYYMMDD time values');
  assert.ok(timeReise.timeValues.includes('18441231'), 'published start value 18441231');
});

/**
 * Store tests: URL state, bounds, subscription and shareable links.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore, readStateFromUrl, stateToQuery, STATE_DEFAULTS, sanitise, PARAM } from '../public/app/store.js';

const fakeLocation = (search = '', pathname = '/') => ({ search, pathname, href: `https://example.org${pathname}${search}` });
const fakeHistory = () => {
  const calls = [];
  return { calls, replaceState: (state, title, url) => calls.push(url) };
};

test('defaults describe the Zürich initial view', () => {
  assert.equal(STATE_DEFAULTS.lat, 47.3769);
  assert.equal(STATE_DEFAULTS.lon, 8.5417);
  assert.ok(STATE_DEFAULTS.zoom >= 10);
  assert.equal(STATE_DEFAULTS.view, 'split');
});

test('readStateFromUrl parses the short parameter names', () => {
  const state = readStateFromUrl('?q=Rhein&from=1700&to=1850&p=e-rara&t=map&lat=47.1&lon=8.2&z=9&sel=e-rara:11&vp=1', STATE_DEFAULTS);
  assert.equal(state.q, 'Rhein');
  assert.equal(state.from, 1700);
  assert.equal(state.to, 1850);
  assert.equal(state.provider, 'e-rara');
  assert.equal(state.type, 'map');
  assert.equal(state.lat, 47.1);
  assert.equal(state.lon, 8.2);
  assert.equal(state.zoom, 9);
  assert.equal(state.selected, 'e-rara:11');
  assert.equal(state.viewport, '1');
});

test('sanitise clamps hostile values instead of breaking the UI', () => {
  const state = sanitise({ ...STATE_DEFAULTS, lat: 999, lon: 500, zoom: 99, from: 1900, to: 1500, view: 'nope', sort: 'nope', viewport: 'true' });
  assert.ok(state.lat <= 85 && state.lat >= -85);
  assert.ok(state.lon >= -180 && state.lon <= 180);
  assert.ok(state.zoom >= 2 && state.zoom <= 18);
  assert.ok(state.from <= state.to, 'range is ordered');
  assert.equal(state.view, 'split');
  assert.equal(state.sort, 'year-asc');
  assert.equal(state.viewport, '1');
});

test('stateToQuery omits defaults and keeps a stable round trip', () => {
  const query = stateToQuery({ ...STATE_DEFAULTS, q: 'Zürich', from: 1600 });
  assert.ok(query.includes(`q=Z%C3%BCrich`));
  assert.ok(query.includes('from=1600'));
  assert.ok(!query.includes('to='), 'unchanged values are not written');
  const roundTrip = readStateFromUrl(`?${query}`, STATE_DEFAULTS);
  assert.equal(roundTrip.q, 'Zürich');
  assert.equal(roundTrip.from, 1600);
  assert.equal(roundTrip.to, STATE_DEFAULTS.to);
});

test('every state key has a documented URL parameter', () => {
  for (const key of Object.keys(STATE_DEFAULTS)) {
    assert.ok(PARAM[key], `${key} needs a URL parameter`);
  }
});

test('update merges, syncs the URL and notifies subscribers once', () => {
  const history = fakeHistory();
  const store = createStore({ history, location: fakeLocation('') });
  const seen = [];
  const unsubscribe = store.subscribe((state, changed) => seen.push({ changed, from: state.from }));
  store.update({ from: 1750 });
  assert.deepEqual(seen.map((entry) => entry.changed), [['from']]);
  assert.match(history.calls.at(-1), /from=1750/);
  store.update({ from: 1750 });
  assert.equal(seen.length, 1, 'no notification without a change');
  unsubscribe();
  store.update({ to: 1800 });
  assert.equal(seen.length, 1, 'unsubscribe works');
});

test('a sandboxed window (no history) still works', () => {
  const store = createStore({ history: null, location: null });
  store.update({ zoom: 7 });
  assert.equal(store.getState().zoom, 7);
});

/**
 * Records/index tests: filtering, sorting, bounds and validation.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import {
  bboxIntersects,
  facets,
  filterRecords,
  indexRecords,
  loadRecords,
  matchesQuery,
  overlapsRange,
  recordCenter,
  recordsInBounds,
  sortRecords,
  validateRecord,
  yearBounds,
} from '../public/app/records.js';

const fixture = [
  {
    id: 'e-rara:1',
    title: 'Karte des Kantons Zürich',
    creators: ['Dufour, Guillaume-Henri'],
    providerId: 'e-rara',
    institution: 'Zentralbibliothek Zürich',
    rights: 'PDM 1.0',
    recordUrl: 'https://www.e-rara.ch/doi/10.3931/e-rara-1',
    thumbnail: 'https://www.e-rara.ch/i3f/v20/1/full/304/0/default.jpg',
    yearStart: 1852,
    yearEnd: 1865,
    type: 'map',
    extent: { west: 8.3, east: 8.9, south: 47.2, north: 47.6 },
    geo: { lat: 47.37, lon: 8.54 },
  },
  {
    id: 'swisstopo:zeitreihen',
    title: 'Zeitreise Kartenwerke',
    creators: [],
    providerId: 'swisstopo',
    institution: 'Bundesamt für Landestopografie',
    rights: 'OGD',
    recordUrl: 'https://map.geo.admin.ch/',
    thumbnail: 'https://wmts.geo.admin.ch/tile.png',
    yearStart: 1844,
    yearEnd: 2021,
    type: 'overlay',
    extent: { west: 5.14, east: 11.47, south: 45.39, north: 48.23 },
  },
];

test('validateRecord accepts good records and reports broken ones', () => {
  assert.deepEqual(validateRecord(fixture[0]), []);
  const problems = validateRecord({ ...fixture[0], recordUrl: 'http://insecure.example', extent: { west: 9, east: 8, south: 47, north: 46 } });
  assert.ok(problems.some((p) => p.includes('https')));
  assert.ok(problems.some((p) => p.includes('extent')));
  assert.ok(validateRecord({ id: 'bad id' }).length > 0);
});

test('matchesQuery is token-based and case-insensitive', () => {
  assert.ok(matchesQuery(fixture[0], 'kantons zürich'));
  assert.ok(matchesQuery(fixture[0], 'DUFOUR'));
  assert.ok(matchesQuery(fixture[0], 'zentralbibliothek'));
  assert.ok(!matchesQuery(fixture[0], 'basel'));
  assert.ok(matchesQuery(fixture[0], ''));
});

test('overlapsRange handles publication ranges and single years', () => {
  assert.ok(overlapsRange(fixture[0], 1800, 1900));
  assert.ok(overlapsRange(fixture[0], 1860, 1870), 'range intersects');
  assert.ok(!overlapsRange(fixture[0], 1900, 1950));
  assert.ok(overlapsRange({ yearStart: 1850, yearEnd: 1850 }, 1850, 1850));
});

test('filterRecords combines keyword, range, provider and type', () => {
  const all = fixture;
  assert.equal(filterRecords({ from: 1400, to: 2100, q: '', provider: '', type: '' }, all).length, 2);
  assert.equal(filterRecords({ from: 1855, to: 1900, q: '', provider: '', type: '' }, all).length, 1);
  assert.equal(filterRecords({ from: 1400, to: 2100, q: '', provider: 'swisstopo', type: '' }, all).length, 1);
  assert.equal(filterRecords({ from: 1400, to: 2100, q: 'zeitreise', provider: '', type: 'overlay' }, all).length, 1);
  assert.equal(filterRecords({ from: 1400, to: 2100, q: 'zeitreise', provider: '', type: 'map' }, all).length, 0);
});

test('sortRecords sorts by year and title', () => {
  assert.deepEqual(sortRecords(fixture, 'year-asc').map((r) => r.yearStart), [1844, 1852]);
  assert.deepEqual(sortRecords(fixture, 'year-desc').map((r) => r.yearStart), [1852, 1844]);
  assert.equal(sortRecords(fixture, 'title')[0].title.startsWith('Karte'), true);
});

test('recordCenter prefers a documented point, then the bbox centre', () => {
  assert.deepEqual(recordCenter(fixture[0]), { lat: 47.37, lon: 8.54 });
  assert.deepEqual(recordCenter(fixture[1]).lat.toFixed(4), '46.8100');
  assert.equal(recordCenter({ id: 'x' }), null);
});

test('bboxIntersects and recordsInBounds respect the viewport', () => {
  assert.ok(bboxIntersects({ west: 8, east: 9, south: 47, north: 48 }, { west: 8.5, east: 9.5, south: 47.5, north: 49 }));
  assert.ok(!bboxIntersects({ west: 8, east: 8.4, south: 47, north: 47.4 }, { west: 9, east: 9.5, south: 48, north: 49 }));
  const inZuerich = recordsInBounds(fixture, { west: 8.4, east: 8.7, south: 47.3, north: 47.5 });
  assert.deepEqual(inZuerich.map((r) => r.id), ['e-rara:1']);
  assert.deepEqual(recordsInBounds(fixture, null).length, 2);
});

test('facets and yearBounds describe the corpus', () => {
  const { providers, types } = facets(fixture);
  assert.equal(providers.get('e-rara'), 1);
  assert.equal(types.get('overlay'), 1);
  assert.deepEqual(yearBounds(fixture), { min: 1844, max: 2021 });
  assert.equal(indexRecords(fixture).get('e-rara:1').title.includes('Zürich'), true);
});

test('loadRecords reads the shipped seed file and validates it', async () => {
  const raw = JSON.parse(await readFile(new URL('../public/data/records.json', import.meta.url), 'utf8'));
  const fetchStub = async () => ({ ok: true, json: async () => raw });
  const result = await loadRecords(fetchStub);
  assert.equal(result.ok, true, result.errors.join('; '));
  assert.equal(result.records.length, raw.records.length);
  assert.ok(result.generatedAt);
});

/**
 * Worker tests: routing, caching stub and the upstream allowlist.
 * `caches.default` does not exist in Node, so a minimal stub is installed.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import worker from '../src/worker/index.js';
import { ALLOWLIST, isAllowed, VERSION } from '../src/worker/allowlist.js';

const store = new Map();
globalThis.caches = {
  default: {
    match: async (request) => store.get(request.url)?.clone(),
    put: async (request, response) => store.set(request.url, response.clone()),
  },
};

const records = JSON.parse(await readFile(new URL('../public/data/records.json', import.meta.url), 'utf8'));
const assets = {
  '/data/records.json': records,
  '/data/sources.json': { providers: [] },
  '/data/overlays.json': { overlays: [] },
};

const env = {
  ASSETS: {
    fetch: async (request) => {
      const url = new URL(request.url);
      const body = assets[url.pathname];
      if (!body) return new Response('not found', { status: 404 });
      return new Response(JSON.stringify(body), { headers: { 'content-type': 'application/json' } });
    },
  },
};

const ctx = { waitUntil: () => {} };
const call = (path, init) => worker.fetch(new Request(`https://example.org${path}`, init), env, ctx);

test('allowlist rejects anything not on an allowlisted https host/path', () => {
  assert.ok(isAllowed(new URL('https://www.e-rara.ch/i3f/v20/1/manifest')));
  assert.ok(isAllowed(new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer?searchText=Z')));
  assert.ok(!isAllowed(new URL('http://www.e-rara.ch/i3f/v20/1/manifest')), 'http is refused');
  assert.ok(!isAllowed(new URL('https://evil.example/i3f/v20/1/manifest')), 'unknown host is refused');
  assert.ok(!isAllowed(new URL('https://www.e-rara.ch/private/admin')), 'unknown path prefix is refused');
  assert.ok(ALLOWLIST.length >= 3);
});

test('GET /api/health reports the runtime and upstreams', async () => {
  const res = await call('/api/health');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.ok, true);
  assert.equal(body.version, VERSION);
  assert.ok(body.upstreams.includes('www.e-rara.ch'));
  assert.ok(body.endpoints.includes('/api/search/places'));
});

test('GET /api/records serves the seed data from the assets binding', async () => {
  const res = await call('/api/records');
  assert.equal(res.status, 200);
  assert.match(res.headers.get('cache-control'), /max-age=300/);
  const body = await res.json();
  assert.equal(body.records.length, records.records.length);
});

test('GET /api/search/places validates the query before touching an upstream', async () => {
  const res = await call('/api/search/places?q=a');
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.equal(body.error, 'query_too_short');
});

test('GET /api/fetch refuses non-allowlisted urls and missing urls', async () => {
  assert.equal((await call('/api/fetch')).status, 400);
  const blocked = await call('/api/fetch?url=https%3A%2F%2Fexample.com%2Fdata');
  assert.equal(blocked.status, 403);
  const body = await blocked.json();
  assert.equal(body.error, 'host_not_allowed');
});

test('unknown /api paths return 404 json and other methods 405', async () => {
  const missing = await call('/api/nope');
  assert.equal(missing.status, 404);
  assert.equal((await missing.json()).error, 'not_found');
  const post = await call('/api/health', { method: 'POST' });
  assert.equal(post.status, 405);
});

test('non-api requests fall through to static assets', async () => {
  const res = await worker.fetch(new Request('https://example.org/index.html'), env, ctx);
  assert.equal(res.status, 404, 'the stub asset store only knows the data files');
});

test('search results are normalised and cached', async () => {
  const upstreamPayload = {
    results: [
      {
        attrs: {
          label: 'Zürich (ZH)',
          origin: 'gg25',
          lat: 47.37721252441406,
          lon: 8.527311325073242,
          zoomlevel: 4294967295,
          geom_st_box2d: 'BOX(8.44688 47.319035,8.627198 47.435142)',
        },
      },
    ],
  };
  const originalFetch = globalThis.fetch;
  let calls = 0;
  globalThis.fetch = async (url) => {
    calls += 1;
    assert.match(String(url), /^https:\/\/api3\.geo\.admin\.ch\/rest\/services\/api\/SearchServer/);
    return new Response(JSON.stringify(upstreamPayload), { headers: { 'content-type': 'application/json' } });
  };
  try {
    const first = await call('/api/search/places?q=Z%C3%BCrich&limit=5');
    assert.equal(first.status, 200);
    const body = await first.json();
    assert.equal(body.results[0].label, 'Zürich (ZH)');
    assert.equal(body.results[0].zoom, null, 'a bogus upstream zoomlevel is dropped');
    assert.deepEqual(body.results[0].bbox, { west: 8.44688, south: 47.319035, east: 8.627198, north: 47.435142 });
    const second = await call('/api/search/places?q=Z%C3%BCrich&limit=5');
    assert.equal(second.status, 200);
    assert.equal(calls, 1, 'the second identical request is served from the edge cache');
  } finally {
    globalThis.fetch = originalFetch;
  }
});

