const ev=async(e)=>(await send('Runtime.evaluate',{expression:e,returnByValue:true,awaitPromise:true})).result.result.value;
const out=await ev(`(async () => {
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  // find a swisstopo overlay record in the list (title starts with "Zeitreise" or has tag Ebene)
  const buttons=[...document.querySelectorAll('#result-list button')];
  const target=buttons.find(b=>/Zeitreise|Siegfried|Dufour/i.test(b.textContent));
  const found= Boolean(target);
  target?.click();
  await sleep(2500);
  const preview=document.querySelector('#detail-preview img');
  const hasButton=[...document.querySelectorAll('#detail button')].some(b=>/Kartenebene/.test(b.textContent));
  const spinnerLeft=!document.querySelector('#detail-preview .zh-spinner') ? false : true;
  const beforeTiles=document.querySelectorAll('.map-overlay-tile').length;
  [...document.querySelectorAll('#detail button')].find(b=>/Kartenebene/.test(b.textContent))?.click();
  await sleep(3000);
  return {found, title: document.querySelector('.app-detail__title')?.textContent?.slice(0,60),
    previewSrc: preview?.getAttribute('src')?.slice(0,80), previewLoaded: preview? preview.naturalWidth>0:false,
    spinnerLeft, hasButton, beforeTiles, afterTiles: document.querySelectorAll('.map-overlay-tile').length,
    afterLoaded: [...document.querySelectorAll('.map-overlay-tile')].filter(i=>i.naturalWidth>0).length,
    overlaySelect: document.querySelector('#overlay-select')?.value,
    status: document.querySelector('#detail-status')?.textContent?.slice(0,80),
    url: location.search.slice(0,80)};
})()`);
